package unit

import (
	"path/filepath"
	"testing"

	"github.com/gruntwork-io/terratest/modules/terraform"
	"github.com/stretchr/testify/assert"
)

func planEndpoint(t *testing.T, vars map[string]interface{}) interface{} {
	options := terraform.WithDefaultRetryableErrors(t, &terraform.Options{
		TerraformDir: "../..",
		PlanFilePath: filepath.Join(t.TempDir(), "plan.tfplan"),
		Vars:         vars,
	})

	plan := terraform.InitAndPlanAndShowWithStruct(t, options)
	return plan.RawPlan.PlannedValues.Outputs["endpoint"].Value
}

func TestEndpointDefaultPort(t *testing.T) {
	t.Parallel()

	got := planEndpoint(t, map[string]interface{}{
		"name": "api",
		"host": "api.example.internal",
	})

	assert.Equal(t, "https://api.example.internal:8443", got)
}

func TestEndpointCustomPort(t *testing.T) {
	t.Parallel()

	got := planEndpoint(t, map[string]interface{}{
		"name": "api",
		"host": "api.example.internal",
		"port": 9443,
	})

	assert.Equal(t, "https://api.example.internal:9443", got)
}
